Simulation: Seeing Variance Decrease

# Population parameters
true_mean &lt;- 120  # True mean systolic BP
true_sd &lt;- 15     # Population standard deviation

# Simulate sample means for different sample sizes
simulation_data &lt;- tibble(n = c(5, 25, 100)) |&gt; 
  cross_join(tibble(sim = 1:2000)) |&gt; 
  mutate(
    sample_mean = map2_dbl(n, sim, \(size, s) {
      mean(rnorm(size, true_mean, true_sd))
    })
  )

# Calculate observed standard deviation for each sample size
simulation_data |&gt; 
  group_by(n) |&gt; 
  summarize(
    observed_sd = sd(sample_mean),
    theoretical_sd = true_sd / sqrt(first(n))
  )

# A tibble: 3 × 3
      n observed_sd theoretical_sd
  &lt;dbl&gt;       &lt;dbl&gt;          &lt;dbl&gt;
1     5        6.64           6.71
2    25        3.00           3   
3   100        1.50           1.5

Likelihood vs. Log-Likelihood: Code

# Compare likelihood and log-likelihood
likelihood_data |&gt; 
  mutate(log_likelihood = log(likelihood)) |&gt; 
  select(p, likelihood, log_likelihood) |&gt; 
  pivot_longer(-p, names_to = "type", values_to = "value") |&gt; 
  mutate(type = case_when(
    type == "likelihood" ~ "Likelihood L(p)",
    type == "log_likelihood" ~ "Log-Likelihood ℓ(p)"
  )) |&gt; 
  ggplot(aes(x = p, y = value)) +
  geom_line(color = "steelblue", linewidth = 1.2) +
  geom_vline(xintercept = mle_p, color = "red", linetype = "dashed") +
  facet_wrap(~type, scales = "free_y") +
  labs(title = "Likelihood vs. Log-Likelihood", 
       subtitle = "Both maximize at the same point",
       x = "Parameter (p)", y = "Value")

Visualizing MLE vs MME: Code

uniform_comparison |&gt; 
  select(mle, mme) |&gt; 
  pivot_longer(everything(), names_to = "Estimator", values_to = "Estimate") |&gt; 
  mutate(Estimator = toupper(Estimator)) |&gt; 
  ggplot(aes(x = Estimate, fill = Estimator)) +
  geom_histogram(bins = 40, alpha = 0.6, position = "identity") +
  geom_vline(xintercept = theta, color = "red", linetype = "dashed", linewidth = 1.2) +
  labs(title = "MLE vs MME for Uniform[0, θ]",
       subtitle = str_glue("True θ = {theta}; MLE is biased but has lower variance"),
       x = "Estimate", y = "Frequency") +
  scale_fill_manual(values = c("steelblue", "darkgreen")) +
  theme(legend.position = "top")

